type cliArgumentTarget struct {
	value    any
	required bool
}

func bindCLIArguments(arguments map[string]jsontext.Value, targets map[string]cliArgumentTarget) error {
	for name, raw := range arguments {
		target, ok := targets[name]
		if !ok {
			return fmt.Errorf("unknown argument %q", name)
		}
		if target.required && bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
			return fmt.Errorf("argument %q cannot be null", name)
		}
		if err := jsonv2.Unmarshal(raw, target.value, jsonv2.RejectUnknownMembers(true)); err != nil {
			return fmt.Errorf("argument %q: %w", name, err)
		}
	}
	for name, target := range targets {
		if _, ok := arguments[name]; target.required && !ok {
			return fmt.Errorf("argument %q is required", name)
		}
	}
	return nil
}

func bindCLIBody[T any](body jsontext.Value, input **T) error {
	if err := jsonv2.Unmarshal(body, input, jsonv2.RejectUnknownMembers(true)); err != nil {
		return fmt.Errorf("JSON body: %w", err)
	}
	if *input == nil {
		return fmt.Errorf("JSON body cannot be null")
	}
	return nil
}

func validCLIKey(key string) bool {
	if len(key) < 1 || len(key) > 128 {
		return false
	}
	for i := range len(key) {
		if key[i] < '!' || key[i] > '~' {
			return false
		}
	}
	return true
}
